import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十三卦 既濟 水火既濟 坎上離下","description":"周易 - 第六十三卦 既濟 水火既濟 坎上離下","frontmatter":{"title":"第六十三卦 既濟 水火既濟 坎上離下","description":"周易 - 第六十三卦 既濟 水火既濟 坎上離下"},"headers":[],"relativePath":"classics/zhouyi/064.md","filePath":"classics/zhouyi/064.md"}'),l={name:"classics/zhouyi/064.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="既濟" tabindex="-1">既濟 <a class="header-anchor" href="#既濟" aria-label="Permalink to “既濟”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，小利貞，初吉終亂。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>既濟，亨，小者亨也。利貞，剛柔正而位當也。初吉，柔得中也。終止則亂，其道窮也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>水在火上，既濟；君子以思患而預防之。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>曳其輪，濡其尾，無咎。象曰：曳其輪，義無咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>婦喪其茀，勿逐，七日得。象曰：七日得，以中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>高宗伐鬼方，三年克之，小人勿用。象曰：三年克之，憊也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>（糹需）有衣袽，終日戒。象曰：終日戒，有所疑也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>東鄰殺牛，不如西鄰之禴祭，實受其福。象曰：東鄰殺牛，不如西鄰之時也；實受其福，吉大來也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>濡其首，厲。象曰：濡其首厲，何可久也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
